  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import {
  resolveSmoothScrollMode,
  shouldEnableLenis,
  shouldPreventLenis,
  SMOOTH_SCROLL_DEFAULTS,
  type SmoothScrollMode,
} from "./smooth-scroll-options";
import { attachGsapLenisSync } from "./smooth-scroll-sync";
