          const current = pathname === item.href;
          return (
            <li key={item.href} className="shrink-0">
              <TransitionLink
                href={item.href}
                aria-current={current ? "page" : undefined}
                className={cn(
                  "whitespace-nowrap text-sm",
                  current ? "text-foreground" : "text-foreground/70",
